sed -i '/item { Text("Backgrounds"/i \        item { Text("Inspirational Quote", style = MaterialTheme.typography.titleLarge) }\n        item {\n            val quote by viewModel.quoteMode.collectAsState()\n            val quotes = listOf("None", "Shuffle", "Per studium ad sapientiam", "Labor omnia vincit", "Assiduitas mater scientiae", "Nulla dies sine linea", "Carpe diem", "Vincit qui se vincit")\n            com.aidict.app.ui.components.SearchableDropdown(\n                label = "Display Quote on Empty Screens",\n                currentValue = quote,\n                options = quotes,\n                onSelected = { viewModel.saveSetting("QUOTE_MODE", it) }\n            )\n        }' android_app/app/src/main/java/com/aidict/app/ui/screens/SettingsScreen.kt
